public class Main {
    public static void main(String[] args) throws Exception {
        Kitty 橘 = new Kitty();

        Field 骨头 = Kitty.class.getDeclaredField("名字");
        骨头.setAccessible(true);
        System.out.println("照之前：" + 骨头.get(橘));
        骨头.set(橘, "大橘");
        System.out.println("照之后：" + 骨头.get(橘));
    }
}

class Kitty {
    private String 名字 = "小橘";
}

